mapper.select:
SELECT SHOPPING_NO
FROM SHOPPING_LIST
WHERE USER_NO = #{userNo}
  AND BOARD_NO = #{boardNo}
LIMIT 1

mapper.delete:
DELETE FROM SHOPPING_LIST
WHERE SHOPPING_NO = #{shoppingNo}
  AND USER_NO = #{userNo}

DELETE FROM SHOPPING_ITEM
WHERE SHOPPING_NO IN (
    SELECT SHOPPING_NO
    FROM SHOPPING_LIST
    WHERE SHOPPING_NO = #{shoppingNo}
      AND USER_NO = #{userNo}
)

mapper.update:
UPDATE SHOPPING_ITEM si
JOIN SHOPPING_LIST sl ON sl.SHOPPING_NO = si.SHOPPING_NO
SET si.ITEM_STATUS = #{itemStatus}
WHERE si.SHOPPING_NO = #{shoppingNo}
  AND si.ITEM_NO = #{itemNo}
  AND sl.USER_NO = #{userNo}

UPDATE SHOPPING_ITEM si
JOIN SHOPPING_LIST sl ON sl.SHOPPING_NO = si.SHOPPING_NO
SET si.ITEM_STATUS = #{itemStatus}
WHERE si.SHOPPING_NO = #{shoppingNo}
  AND sl.USER_NO = #{userNo}
